    Bug 2038289 - Oauth unavailable in account hub manual config select dropdown. r=klamping


    **How to Test**
    - Open account hub and enter an email and click manual configuration
    - Select EWS and enter https://outlook.office365.com/EWS/Exchange.asmx
    - OAuth should be available as an authentication method

    Differential Revision: https://phabricator.services.mozilla.com/D303412

diff --git a/mail/components/accountcreation/content/widgets/account-hub-select.mjs b/mail/components/accountcreation/content/widgets/account-hub-select.mjs
index f6ccb0a8b1d..4cb21195216 100644
--- a/mail/components/accountcreation/content/widgets/account-hub-select.mjs
+++ b/mail/components/accountcreation/content/widgets/account-hub-select.mjs
@@ -144,8 +144,7 @@ class AccountHubSelect extends HTMLElement {
   }

   /**
-   *  Update the options based on
-   * the mutations observed.
+   * Update the options based on the mutations observed.
    *
    * @param {MutationRecord} mutationRecord - The mutation record for the
    *  observed changes.
@@ -155,10 +154,14 @@ class AccountHubSelect extends HTMLElement {
     const element = this.select.querySelector(`#${target.id}`);
     switch (mutationRecord.type) {
       case "attributes":
-        element.setAttribute(
-          mutationRecord.attributeName,
-          target.getAttribute(mutationRecord.attributeName)
-        );
+        if (!target.hasAttribute(mutationRecord.attributeName)) {
+          element.removeAttribute(mutationRecord.attributeName);
+        } else {
+          element.setAttribute(
+            mutationRecord.attributeName,
+            target.getAttribute(mutationRecord.attributeName)
+          );
+        }
         break;
       case "characterData":
         element.textContent = target.textContent;
diff --git a/mail/components/accountcreation/test/browser/browser_accountHubSelect.js b/mail/components/accountcreation/test/browser/browser_accountHubSelect.js
